function setHeroSlide(index){const root=document.querySelector('.home-hero');if(!root)return;heroIndex=(index+heroSlides.length)%heroSlides.length;const activeSlide=root.querySelectorAll('.hero-slide')[heroIndex];if(activeSlide&&!activeSlide.style.backgroundImage)activeSlide.style.backgroundImage=`url('${heroSlides[heroIndex].image}'),url('/assets/campaign-${heroSlides[heroIndex].shop.toLowerCase()==='basketball'?'basketball':heroSlides[heroIndex].shop.toLowerCase()}.svg')`;root.querySelectorAll('.hero-slide').forEach((el,i)=>el.classList.toggle('is-active',i===heroIndex));root.querySelectorAll('.hero-dot').forEach((el,i)=>{el.classList.toggle('is-active',i===heroIndex);el.setAttribute('aria-pressed',String(i===heroIndex))});root.querySelector('#heroSlideCount').textContent=String(heroIndex+1).padStart(2,'0')+' / 04';root.querySelector('#heroSlideName').textContent=heroSlides[heroIndex].category+' / '+heroSlides[heroIndex].caption;const collection=root.querySelector('#heroCollection');if(collection){collection.textContent='DISCOVER '+heroSlides[heroIndex].shop.toUpperCase()+' ↗';collection.href='#/shop?category='+heroSlides[heroIndex].shop;}const sneaker=root.querySelector('#heroShoeImage');if(sneaker){sneaker.src=heroSlides[heroIndex].shoe;sneaker.alt=heroSlides[heroIndex].shop+' footwear photographed in studio';}const sneakerLabel=root.querySelector('#heroSneakerCategory');if(sneakerLabel)sneakerLabel.textContent=heroSlides[heroIndex].category+' / THE SHOES';root.style.setProperty('--hero-shoe-accent',heroSlides[heroIndex].accent);root.style.setProperty('--slide-index',heroIndex);root.classList.remove('slide-restart');void root.offsetWidth;root.classList.add('slide-restart')}
function initHeroSlider(){stopHeroSlider();heroIndex=0;const root=document.querySelector('.home-hero');if(!root)return;root.querySelectorAll('[data-hero-slide]').forEach(btn=>btn.addEventListener('click',()=>{setHeroSlide(Number(btn.dataset.heroSlide));restart()}));root.querySelector('#heroPrev').addEventListener('click',()=>{setHeroSlide(heroIndex-1);restart()});root.querySelector('#heroNext').addEventListener('click',()=>{setHeroSlide(heroIndex+1);restart()});function restart(){stopHeroSlider();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)heroTimer=setInterval(()=>{if(!document.hidden)setHeroSlide(heroIndex+1)},5500)}root.addEventListener('mouseenter',stopHeroSlider);root.addEventListener('mouseleave',restart);root.addEventListener('focusin',stopHeroSlider);root.addEventListener('focusout',e=>{if(!root.contains(e.relatedTarget))restart()});restart()}
