function initMotionLab(){const lab=document.getElementById('motionLab');if(!lab)return;const options={Running:['GO THE DISTANCE.','From the first easy kilometre to your next finish line.'],Training:['SHOW UP. REPEAT.','Stable, flexible footwear made for the work you put in.'],Basketball:['BRING YOUR GAME.','Support and confidence for every cut, jump and drive.'],Lifestyle:['LIVE IN MOTION.','The everyday pairs you reach for without thinking twice.'],Outdoor:['TAKE THE LONG WAY.','Find your footing when the path gets a little less familiar.'],Walking:['EVERY STEP MATTERS.','Easy comfort for commutes, walks and everywhere in between.']};const keys=Object.keys(options);lab.querySelectorAll('[data-lab-category]').forEach(button=>button.addEventListener('click',()=>{const c=button.dataset.labCategory,idx=keys.indexOf(c),count=String(idx+1).padStart(2,'0')+' / 06';lab.dataset.mode=c;lab.querySelectorAll('[data-lab-category]').forEach(el=>{const active=el===button;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active))});lab.querySelector('#labIndex').textContent=count;lab.querySelector('#labArtIndex').textContent=count;lab.querySelector('#labTitle').textContent=options[c][0];lab.querySelector('#labDescription').textContent=options[c][1];const link=lab.querySelector('#labLink');link.href='#/shop?category='+encodeURIComponent(c);link.setAttribute('aria-label','Shop '+c+' footwear');lab.querySelector('.lab-rings').classList.remove('lab-pulse');void lab.offsetWidth;lab.querySelector('.lab-rings').classList.add('lab-pulse')}))}
function initTilt(){
 const area=document.getElementById('tiltArea'),stage=document.getElementById('tiltStage');
 if(!area||matchMedia('(prefers-reduced-motion: reduce)').matches||!matchMedia('(pointer:fine)').matches)return;
 let frame=0;
 area.addEventListener('pointermove',e=>{const rect=area.getBoundingClientRect(),rx=(((e.clientY-rect.top)/rect.height)-.5)*-15,ry=(((e.clientX-rect.left)/rect.width)-.5)*18;if(frame)cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{stage.style.setProperty('--rx',rx+'deg');stage.style.setProperty('--ry',ry+'deg');frame=0})});
 area.addEventListener('pointerleave',()=>{if(frame)cancelAnimationFrame(frame);stage.style.setProperty('--rx','0deg');stage.style.setProperty('--ry','0deg')})
}
