function updateZoomUI(){
 for(const id of ['photoImageWrap','photoLightbox']){const element=document.getElementById(id);if(element)element.style.setProperty('--gallery-zoom',String(galleryZoom));}
 for(const id of ['photoZoomPercent','lightboxZoomPercent']){const el=document.getElementById(id);if(el)el.textContent=Math.round(galleryZoom*100)+'%';}
 document.querySelectorAll('[data-gallery-zoom="in"]').forEach(b=>b.disabled=galleryZoom>=GALLERY_ZOOM_MAX);
 document.querySelectorAll('[data-gallery-zoom="out"]').forEach(b=>b.disabled=galleryZoom<=GALLERY_ZOOM_MIN);
}
function setGalleryZoom(action){
 const next=action==='reset'?1:galleryZoom+(action==='in'?GALLERY_ZOOM_STEP:-GALLERY_ZOOM_STEP);
 galleryZoom=Math.min(GALLERY_ZOOM_MAX,Math.max(GALLERY_ZOOM_MIN,Math.round(next*100)/100));
 updateZoomUI();
}
function refreshGallery(){
 const p=byId(galleryProductId),main=document.getElementById('photoMain');if(!p||!main)return;
 const frames=galleryImages(p),f=frames[galleryIndex];main.src=f.src;main.alt=p.name+' — '+f.label;
 document.getElementById('photoCount').textContent=String(galleryIndex+1).padStart(2,'0')+' / '+String(frames.length).padStart(2,'0');
 document.getElementById('photoLabel').textContent=f.label;
 document.querySelectorAll('[data-gallery-index]').forEach(btn=>{const active=Number(btn.dataset.galleryIndex)===galleryIndex;btn.classList.toggle('is-selected',active);btn.setAttribute('aria-pressed',String(active));if(active&&galleryIndex>2)btn.parentElement?.scrollTo({left:btn.offsetLeft-btn.parentElement.offsetLeft-40,behavior:'smooth'})});
 const lb=document.getElementById('photoLightbox');if(lb&&lb.open){const img=document.getElementById('lightboxImage');img.src=f.src;img.alt=main.alt;const viewport=document.getElementById('photoPanViewport');if(viewport){viewport.scrollLeft=0;viewport.scrollTop=0;}document.getElementById('lightboxLabel').textContent=f.label+' · '+String(galleryIndex+1).padStart(2,'0')+' / '+String(frames.length).padStart(2,'0');}
 updateZoomUI();
}
function changeGallery(delta){
 const p=byId(galleryProductId);if(!p)return;
 const frames=galleryImages(p);if(frames.length<2)return;
 galleryIndex=(galleryIndex+delta+frames.length)%frames.length;
 galleryZoom=1; // Changing views NEVER zooms the image; the plus/minus dock alone controls scale.
 refreshGallery();
}
function openPhotoLightbox(){
 const p=byId(galleryProductId);if(!p)return;
 const lb=document.getElementById('photoLightbox'),frames=galleryImages(p),f=frames[galleryIndex];
 document.getElementById('lightboxImage').src=f.src;
 document.getElementById('lightboxImage').alt=p.name+' — '+f.label;
 document.getElementById('lightboxLabel').textContent=f.label+' · '+String(galleryIndex+1).padStart(2,'0')+' / '+String(frames.length).padStart(2,'0');
 lb.querySelector('#lightboxPrev').hidden=frames.length<2;
 lb.querySelector('#lightboxNext').hidden=frames.length<2;
 lb.showModal();const viewport=document.getElementById('photoPanViewport');if(viewport){viewport.scrollLeft=0;viewport.scrollTop=0;}updateZoomUI();
}
function initGallerySwipe(){
 const stage=document.getElementById('photoStage');if(!stage)return;
 let startX=null;
 stage.addEventListener('touchstart',e=>{if(e.touches.length===1)startX=e.touches[0].clientX},{passive:true});
 stage.addEventListener('touchend',e=>{if(startX===null)return;const dx=e.changedTouches[0].clientX-startX;startX=null;if(Math.abs(dx)>50)changeGallery(dx<0?1:-1)},{passive:true});
}

function addItem(id){if(!selectedSize){notify('Please choose your UK size first.');return}const found=cart.find(x=>x.id===id&&x.size===selectedSize);if(found){if(found.qty>=10){notify('Maximum 10 pairs per size.');return}found.qty++}else cart.push({id,size:selectedSize,qty:1});updateBag();notify('Added to your bag');openCart()}
function closeLayer(){document.getElementById('overlay').hidden=true;document.getElementById('cartDrawer').hidden=true;document.getElementById('authModal').hidden=true;document.body.style.overflow=''}
function openLayer(id){document.getElementById('overlay').hidden=false;document.getElementById(id).hidden=false;document.body.style.overflow='hidden'}
function openCart(){const d=document.getElementById('cartDrawer');const t=sum();d.innerHTML=`<div class="drawer-head"><h2>YOUR BAG / ${cart.reduce((n,x)=>n+x.qty,0)}</h2><button class="x" data-close aria-label="Close">×</button></div><hr class="mini-divider">${cart.length?cart.map((x,i)=>{const p=byId(x.id);return `<div class="summary-product"><img src="${p.img}" data-photo-fallback="true" alt=""><div><strong>${escapeHtml(p.name)}</strong><small>UK ${x.size} · ${money(p.price)} / PAIR</small><div class="bag-item-actions"><div class="qty-control"><button type="button" data-qty-step="-1" data-qty-index="${i}" aria-label="Reduce quantity of ${escapeHtml(p.name)}">−</button><span aria-label="Quantity">${x.qty}</span><button type="button" data-qty-step="1" data-qty-index="${i}" aria-label="Increase quantity of ${escapeHtml(p.name)}">+</button></div><button class="text-btn" data-remove="${i}">REMOVE</button></div></div></div>`}).join(''):'<div class="empty"><h2>NOTHING IN HERE.</h2><p>Find your next pair.</p><a href="#/shop" class="btn" data-close>SHOP SHOES ↗</a></div>'}${cart.length?`<div class="shipping-hint">${t.shipping?`ADD ${money(3999-t.subtotal)} MORE FOR FREE SHIPPING`:'FREE SHIPPING UNLOCKED ✓'}</div><div class="summary-line"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="summary-line"><span>Delivery</span><b>${t.shipping?money(t.shipping):'FREE'}</b></div><div class="summary-line total"><span>Total</span><span>${money(t.total)}</span></div><button class="btn" id="goCheckout">CHECKOUT <span>↗</span></button><p class="small-note">Cash on Delivery available.</p>`:''}`;openLayer('cartDrawer')}
function openAuth(mode='login'){const m=document.getElementById('authModal');if(user){m.innerHTML=`<div class="auth-head"><span class="overline">YOUR PROFILE</span><button class="x" data-close aria-label="Close">×</button></div><h2>HI, ${escapeHtml(user.name.split(' ')[0]).toUpperCase()}.</h2><p>${escapeHtml(user.email)}</p><p class="muted">Your addresses and orders are saved to your local store account.</p><a class="btn" href="#/orders" data-close>VIEW MY ORDERS ↗</a><br><button class="text-btn" id="logout">LOG OUT</button>`;return openLayer('authModal')}
 const signup=mode==='signup';m.innerHTML=`<div class="auth-head"><span class="overline">AUVRYKO ACCOUNT</span><button class="x" data-close aria-label="Close">×</button></div><h2>${signup?'JOIN THE MOVEMENT.':'WELCOME BACK.'}</h2><p class="muted">${signup?'Create an account to save delivery addresses and order history.':'Sign in to continue with your orders.'}</p><form id="authForm">${signup?'<label class="field">FULL NAME<input name="name" required minlength="2" maxlength="60" autocomplete="name"></label>':''}<label class="field">EMAIL<input name="email" type="email" required autocomplete="email"></label><label class="field">PASSWORD<input name="password" type="password" minlength="8" required autocomplete="${signup?'new-password':'current-password'}"></label><button class="btn" type="submit">${signup?'CREATE ACCOUNT':'LOG IN'} ↗</button></form><button class="text-btn" id="toggleAuth">${signup?'ALREADY HAVE AN ACCOUNT? LOG IN':'NEW HERE? CREATE AN ACCOUNT'}</button><p class="small-note">Create your account to save addresses and order history.</p>`;m.dataset.mode=mode;openLayer('authModal')}
async function onAuth(e){e.preventDefault();const form=new FormData(e.target),mode=document.getElementById('authModal').dataset.mode;try{const d=await api('/auth/'+(mode==='signup'?'signup':'login'),{method:'POST',body:JSON.stringify(Object.fromEntries(form))});user=d.user;closeLayer();notify('Signed in as '+user.name);await loadAccount();render()}catch(ex){notify(ex.message)}}
async function loadAccount(){if(!user){addresses=[];orders=[];return}try{const [a,o]=await Promise.all([api('/addresses'),api('/orders')]);addresses=a.addresses;orders=o.orders}catch(e){notify(e.message)}}
function addressText(a){return `${escapeHtml(a.line1)}${a.landmark?', '+escapeHtml(a.landmark):''}, ${escapeHtml(a.city)}, ${escapeHtml(a.state)} — ${escapeHtml(a.pin)}`}
function addressForm(){const a=addresses.find(a=>a.id===editingAddress)||{};const fields=[['name','FULL NAME','text','name'],['phone','MOBILE NUMBER','tel','tel-national'],['line1','HOUSE / STREET / AREA','text','address-line1'],['landmark','LANDMARK (OPTIONAL)','text','off'],['city','CITY','text','address-level2'],['state','STATE','text','address-level1'],['pin','PIN CODE','text','postal-code']];return `<form id="addressForm"><div class="field-grid">${fields.map(([k,label,type,auto])=>`<label class="field ${['line1','landmark'].includes(k)?'full':''}">${label}<input name="${k}" type="${type}" value="${escapeHtml(a[k]||'')}" autocomplete="${auto}" ${k==='landmark'?'':'required'} ${k==='phone'?'pattern="[6-9][0-9]{9}" maxlength="10"':''} ${k==='pin'?'pattern="[1-9][0-9]{5}" maxlength="6"':''}></label>`).join('')}</div><button class="btn" type="submit">${editingAddress?'UPDATE ADDRESS':'SAVE ADDRESS'} ↗</button>${addresses.length?'<button class="text-btn" type="button" id="cancelAddress">CANCEL</button>':''}</form>`}
function checkoutPage(){if(!user){app.innerHTML=`<div class="simple-page"><span class="overline">YOUR CHECKOUT</span><h1>SIGN IN FIRST.</h1><p class="muted">Create an account or log in to save your address and place a COD order.</p><button class="btn" id="checkoutSignIn">LOGIN / SIGN UP ↗</button></div>`;return}if(!cart.length){emptyPage('YOUR BAG IS EMPTY.','Explore the collection and add your favourite pair.');return}if(!chosenAddress&&addresses.length)chosenAddress=addresses[0].id;if(!addresses.length)showAddress=true;const t=sum();app.innerHTML=`<div class="simple-page"><a class="bread" href="#/shop">← CONTINUE SHOPPING</a><span class="overline" style="display:block">CHECKOUT / PAYMENT</span><h1>ALMOST YOURS.</h1><div class="checkout-grid"><div><section class="panel"><h2>01 / DELIVERY ADDRESS</h2>${addresses.map(a=>`<label class="address-tile"><input type="radio" name="addressChoice" value="${a.id}" ${chosenAddress===a.id?'checked':''}><div style="flex:1"><strong>${escapeHtml(a.name)} / ${escapeHtml(a.phone)}</strong><p>${addressText(a)}</p><div class="small-actions"><button class="text-btn" type="button" data-edit-address="${a.id}">EDIT</button><button class="text-btn" type="button" data-delete-address="${a.id}">DELETE</button></div></div></label>`).join('')}${showAddress?addressForm():`<button class="text-btn" id="newAddress">+ ADD NEW ADDRESS</button>`}</section><section class="panel"><h2>02 / PAYMENT METHOD</h2><div class="address-tile"><input type="radio" checked aria-label="Cash on Delivery"><div><strong>CASH ON DELIVERY (COD)</strong><p>Pay on delivery. No card or UPI details required.</p></div></div></section><button class="btn" id="placeOrder" style="width:100%">PLACE ORDER · ${money(t.total)} <span>↗</span></button><p class="small-note">Your order will be saved to your account after confirmation.</p></div><aside class="panel"><h2>YOUR ORDER</h2>${cart.map(x=>{const p=byId(x.id);return `<div class="summary-product"><img src="${p.img}" data-photo-fallback="true" alt=""><div><strong>${escapeHtml(p.name)}</strong><small>UK ${x.size} · QTY ${x.qty}</small></div><strong>${money(p.price*x.qty)}</strong></div>`}).join('')}<div class="summary-line"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="summary-line"><span>Shipping</span><strong>${t.shipping?money(t.shipping):'FREE'}</strong></div><div class="summary-line total"><span>Total</span><strong>${money(t.total)}</strong></div></aside></div></div>`}
async function saveAddress(e){e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));try{const edit=!!editingAddress;const resp=await api('/addresses'+(edit?'/'+editingAddress:''),{method:edit?'PUT':'POST',body:JSON.stringify(obj)});if(edit)addresses=addresses.map(a=>a.id===editingAddress?resp.address:a);else addresses.push(resp.address);chosenAddress=resp.address.id;editingAddress=null;showAddress=false;notify('Address saved to your account');checkoutPage()}catch(err){notify(err.message)}}
async function deleteAddress(id){if(!confirm('Delete this saved address?'))return;try{await api('/addresses/'+id,{method:'DELETE'});addresses=addresses.filter(a=>a.id!==id);chosenAddress=addresses[0]?.id||null;showAddress=!addresses.length;checkoutPage()}catch(e){notify(e.message)}}
async function placeOrder(){if(!chosenAddress){notify('Save and select a delivery address.');return}const btn=document.getElementById('placeOrder');btn.disabled=true;try{const resp=await api('/orders',{method:'POST',body:JSON.stringify({addressId:chosenAddress,items:cart})});lastOrder=resp.order;orders.unshift(resp.order);cart=[];updateBag();routeTo('/success/'+resp.order.id)}catch(e){notify(e.message);btn.disabled=false}}
function orderSummary(o){return `<article class="order-card"><div class="order-head"><div><strong>#${escapeHtml(o.id)}</strong><small>${new Date(o.createdAt).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})} · ${escapeHtml(o.payment)}</small></div><span class="status">${escapeHtml(o.status)}</span></div>${o.items.map(x=>`<div class="summary-product"><img src="${x.img}" data-photo-fallback="true" alt=""><div><strong>${escapeHtml(x.name)}</strong><small>UK ${x.size} / QTY ${x.qty}</small></div><strong>${money(x.price*x.qty)}</strong></div>`).join('')}<div class="summary-line"><div><strong>DELIVERY ADDRESS</strong><p class="muted">${escapeHtml(o.address.name)} / ${escapeHtml(o.address.phone)}<br>${addressText(o.address)}</p></div><div><strong>TOTAL</strong><p>${money(o.total)}</p></div></div></article>`}
function ordersPage(){if(!user){app.innerHTML=`<div class="simple-page"><h1>YOUR ORDERS.</h1><p class="muted">Sign in to see your saved orders.</p><button class="btn" id="checkoutSignIn">LOGIN / SIGN UP ↗</button></div>`;return}app.innerHTML=`<div class="simple-page"><span class="overline">YOUR ACCOUNT / ORDER HISTORY</span><h1>YOUR ORDERS.</h1><p class="muted">Saved under ${escapeHtml(user.email)}. </p>${orders.length?orders.map(orderSummary).join(''):'<div class="empty"><h2>NO ORDERS YET.</h2><p>Your order history will appear here.</p><a href="#/shop" class="btn">SHOP THE COLLECTION ↗</a></div>'}</div>`}
function successPage(id){const o=orders.find(x=>x.id===id)||lastOrder;if(!o||o.id!==id){routeTo('/orders');return}app.innerHTML=`<div class="simple-page"><div class="success-mark">✓</div><span class="overline">COD ORDER / CONFIRMED</span><h1>ORDER SAVED.</h1><p>Your COD order <strong>#${escapeHtml(o.id)}</strong> is in your account history.</p><p>Total payable on delivery: <strong>${money(o.total)}</strong>.</p><p class="muted">Your order details are available in Order History.</p><a href="#/orders" class="btn">VIEW ORDER HISTORY ↗</a></div>`}
function emptyPage(heading,desc){app.innerHTML=`<div class="simple-page"><div class="empty"><h2>${heading}</h2><p>${desc}</p><a class="btn" href="#/shop">SHOP ALL SHOES ↗</a></div></div>`}
function notFound(){app.innerHTML=`<div class="simple-page"><h1>NOT FOUND.</h1><a href="#/shop" class="btn">BACK TO SHOP ↗</a></div>`}
function updateNavigation(path){
 const raw=path.split('?')[0],params=new URLSearchParams(path.split('?')[1]||'');
 let active=raw==='/'||raw===''?'home':raw==='/orders'?'orders':'';
 const category=params.get('category');
 if(raw==='/shop')active=category&&['Running','Training','Basketball','Lifestyle'].includes(category)?category:'shop';
 if(raw.startsWith('/product/')){const item=byId(raw.split('/')[2]);active=item&&['Running','Training','Basketball','Lifestyle'].includes(item.category)?item.category:'shop'}
 document.querySelectorAll('[data-nav]').forEach(el=>{const selected=el.dataset.nav===active;el.classList.toggle('nav-current',selected);el.setAttribute('aria-current',selected?'page':'false')});
 const titles={home:'HOME / THE MOVEMENT DEPARTMENT',shop:'SHOP ALL / 36 STYLES',Running:'RUNNING / THE ROAD COLLECTION',Training:'TRAINING / THE STUDIO EDIT',Basketball:'COURT / GAME DAY',Lifestyle:'EVERYDAY / CITY ROTATION',orders:'YOUR ACCOUNT / ORDERS'};
 const message=raw==='/shop'&&params.get('collection')==='new'?'NEW ARRIVALS / THE LATEST DROP':raw==='/shop'&&params.get('collection')==='saved'?'YOUR SAVED PAIRS':titles[active]||(raw==='/checkout'?'YOUR BAG / CHECKOUT':raw.startsWith('/product/')?'THE FOOTWEAR EDIT / PRODUCT DETAIL':'AUVRYKO');
 const strip=document.getElementById('routeStripLabel');if(strip)strip.textContent=message;
 document.documentElement.classList.toggle('is-shop-route',raw==='/shop');
 document.title=(message.split(' / ')[0]||'AUVRYKO')+' — AUVRYKO';
}
let revealObserver=null;function initReveals(){if(revealObserver){revealObserver.disconnect();revealObserver=null}if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const targets=[...app.querySelectorAll('[data-reveal]')];if(!targets.length)return;revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}},{threshold:0.08,rootMargin:'0px 0px -35px 0px'});for(const el of targets){el.classList.add('will-reveal');revealObserver.observe(el)}}
function closeMobileMenu(){document.getElementById('siteHeader').classList.remove('mobile-open');document.getElementById('menuButton').setAttribute('aria-expanded','false');document.getElementById('menuButton').setAttribute('aria-label','Open navigation')}
document.getElementById('menuButton').addEventListener('click',()=>{const header=document.getElementById('siteHeader'),open=!header.classList.contains('mobile-open');header.classList.toggle('mobile-open',open);document.getElementById('menuButton').setAttribute('aria-expanded',String(open));document.getElementById('menuButton').setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.querySelectorAll('#primaryNav a').forEach(link=>link.addEventListener('click',()=>{closeMobileMenu();if(link.getAttribute('href')===location.hash){link.classList.remove('nav-tapped');void link.offsetWidth;link.classList.add('nav-tapped');window.scrollTo({top:0,behavior:'smooth'})}}));
document.querySelectorAll('a[href="#/"]').forEach(link=>link.addEventListener('click',()=>{if(pathNow()==='/'){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});const root=document.querySelector('.home-hero');if(root){setHeroSlide(0);root.classList.remove('home-replay');void root.offsetWidth;root.classList.add('home-replay')}const bar=document.querySelector('.header-motion');bar.classList.remove('home-activated');void bar.offsetWidth;bar.classList.add('home-activated')}}));
function render(){stopHeroSlider();closeLayer();closeMobileMenu();const path=pathNow();if(path==='/'||path==='')home();else if(path.startsWith('/shop'))shop(path);else if(/^\/product\/\d+$/.test(path))detail(path.split('/')[2]);else if(path==='/checkout')checkoutPage();else if(path==='/orders')ordersPage();else if(path.startsWith('/success/'))successPage(path.substring(9));else notFound();updateNavigation(path);document.documentElement.classList.add('route-switching');window.scrollTo({top:0,left:0,behavior:'instant'});document.documentElement.scrollTop=0;requestAnimationFrame(()=>{window.scrollTo({top:0,left:0,behavior:'instant'});document.documentElement.classList.remove('route-switching');updateScrollProgress()});initReveals();app.classList.remove('page-enter');void app.offsetWidth;app.classList.add('page-enter')}
app.addEventListener('click',e=>{const galleryZoomButton=e.target.closest('[data-gallery-zoom]');if(galleryZoomButton){setGalleryZoom(galleryZoomButton.dataset.galleryZoom);return}const galleryThumb=e.target.closest('[data-gallery-index]');if(galleryThumb){galleryIndex=Number(galleryThumb.dataset.galleryIndex);refreshGallery();return}const photoStep=e.target.closest('[data-photo-step]');if(photoStep){changeGallery(Number(photoStep.dataset.photoStep));return}if(e.target.closest('#photoExpand') || e.target.closest('#photoMain')){openPhotoLightbox();return}const save=e.target.closest('[data-save]');if(save){e.preventDefault();e.stopPropagation();toggleSaved(Number(save.dataset.save));return}const btn=e.target.closest('button'),card=e.target.closest('[data-product]');if(card){routeTo('/product/'+card.dataset.product);return}if(!btn)return;if(btn.dataset.category){filter=btn.dataset.category;const suffix=filter==='New'?'?collection=new':filter==='Saved'?'?collection=saved':filter==='All'?'':'?category='+encodeURIComponent(filter);history.replaceState(null,'','#/shop'+suffix);shop(pathNow());updateNavigation(pathNow())}else if(btn.dataset.size){selectedSize=Number(btn.dataset.size);app.querySelectorAll('[data-size]').forEach(el=>{const active=Number(el.dataset.size)===selectedSize;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active))})}else if(btn.id==='addToBag')addItem(Number(btn.dataset.id));else if(btn.id==='checkoutSignIn')openAuth();else if(btn.id==='newAddress'){showAddress=true;editingAddress=null;checkoutPage()}else if(btn.id==='cancelAddress'){showAddress=false;editingAddress=null;checkoutPage()}else if(btn.dataset.editAddress){editingAddress=btn.dataset.editAddress;showAddress=true;checkoutPage()}else if(btn.dataset.deleteAddress)deleteAddress(btn.dataset.deleteAddress);else if(btn.id==='placeOrder')placeOrder()});
app.addEventListener('keydown',e=>{const c=e.target.closest('[data-product]');if(c&&e.target===c&&(e.key==='Enter'||e.key===' ')){e.preventDefault();routeTo('/product/'+c.dataset.product)}});
app.addEventListener('input',e=>{if(e.target.id==='searchShoes'){search=e.target.value.toLowerCase().trim();renderShop()}});
app.addEventListener('change',e=>{if(e.target.name==='addressChoice'){chosenAddress=e.target.value;checkoutPage()}if(e.target.id==='sortShoes'){sortBy=e.target.value;renderShop()}});
app.addEventListener('submit',e=>{if(e.target.id==='addressForm')saveAddress(e)});
document.getElementById('cartButton').addEventListener('click',openCart);document.getElementById('accountButton').addEventListener('click',()=>openAuth());document.getElementById('mobileAccountAction').addEventListener('click',()=>{closeMobileMenu();openAuth()});document.getElementById('overlay').addEventListener('click',closeLayer);
document.getElementById('cartDrawer').addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeLayer();const rem=e.target.closest('[data-remove]');if(rem){cart.splice(Number(rem.dataset.remove),1);updateBag();openCart()}const step=e.target.closest('[data-qty-step]');if(step){const i=Number(step.dataset.qtyIndex),delta=Number(step.dataset.qtyStep);if(cart[i]){cart[i].qty=Math.max(0,Math.min(10,cart[i].qty+delta));if(!cart[i].qty)cart.splice(i,1);updateBag();openCart()}}if(e.target.id==='goCheckout'){closeLayer();routeTo('/checkout')}});
document.getElementById('authModal').addEventListener('click',async e=>{if(e.target.closest('[data-close]'))closeLayer();if(e.target.id==='toggleAuth')openAuth(document.getElementById('authModal').dataset.mode==='signup'?'login':'signup');if(e.target.id==='logout'){await api('/auth/logout',{method:'POST'});user=null;await loadAccount();closeLayer();routeTo('/');notify('Signed out')}});
document.getElementById('authModal').addEventListener('submit',e=>{if(e.target.id==='authForm')onAuth(e)});
if('scrollRestoration' in history)history.scrollRestoration='manual';window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeLayer();closeMobileMenu()}});

// Theme is site-wide and persistent; no change to commerce/account state.
function applyTheme(mode,persist=true){
 const theme=mode==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;
 if(persist){try{localStorage.setItem('sd_theme_v7',theme)}catch{}}
 const toggle=document.getElementById('themeToggle');
 if(toggle){const isDark=theme==='dark';toggle.setAttribute('aria-pressed',String(isDark));toggle.setAttribute('aria-label',isDark?'Switch to light mode':'Switch to dark mode');toggle.title=isDark?'Switch to light mode':'Switch to dark mode';toggle.querySelector('.theme-icon').textContent=isDark?'☀':'☾';toggle.querySelector('.theme-label').textContent=isDark?'LIGHT':'DARK'}
 const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',theme==='dark'?'#121916':'#f5f3ed');
}
document.getElementById('themeToggle').addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
applyTheme(document.documentElement.dataset.theme,false);
const progressEl=document.getElementById('scrollProgress');
let scrollRaf=false;
function updateScrollProgress(){scrollRaf=false;const max=document.documentElement.scrollHeight-window.innerHeight;progressEl.style.transform=`scaleX(${max>0?Math.max(0,Math.min(1,window.scrollY/max)):0})`}
window.addEventListener('scroll',()=>{if(!scrollRaf){scrollRaf=true;requestAnimationFrame(updateScrollProgress)}},{passive:true});
window.addEventListener('resize',updateScrollProgress,{passive:true});

(async function init(){try{const [p,me]=await Promise.all([api('/products'),api('/auth/me')]);products=p.products;user=me.user;restoreCart();restoreSaved();await loadAccount();render()}catch(e){app.innerHTML='<div class="simple-page"><h1>SERVER NOT CONNECTED.</h1><p>Start the site using <code>npm start</code> (not by opening index.html directly).</p></div>';notify(e.message)}})();

// Internet-hosted product photographs: show a neutral unavailable state if offline, never a cartoon shoe.
document.addEventListener('error',event=>{const img=event.target;
 if(img instanceof HTMLImageElement && img.hasAttribute('data-photo-fallback') && !img.dataset.failed){img.dataset.failed='1';img.classList.add('photo-unavailable');img.alt='Photograph unavailable — check internet connection';}
},true);

// Full-screen studio: navigation and zoom are separate interactions.
const lightbox=document.getElementById('photoLightbox');
document.getElementById('lightboxClose').addEventListener('click',()=>lightbox.close());
document.getElementById('lightboxPrev').addEventListener('click',()=>changeGallery(-1));
document.getElementById('lightboxNext').addEventListener('click',()=>changeGallery(1));
lightbox.addEventListener('click',e=>{const z=e.target.closest('[data-gallery-zoom]');if(z){setGalleryZoom(z.dataset.galleryZoom);return}if(e.target===lightbox)lightbox.close()});
const photoPanViewport=document.getElementById('photoPanViewport');
let photoDrag=null;
photoPanViewport.addEventListener('pointerdown',e=>{if(galleryZoom<=1||e.button!==0)return;photoDrag={x:e.clientX,y:e.clientY,left:photoPanViewport.scrollLeft,top:photoPanViewport.scrollTop};photoPanViewport.setPointerCapture(e.pointerId);photoPanViewport.classList.add('is-dragging')});
photoPanViewport.addEventListener('pointermove',e=>{if(!photoDrag)return;photoPanViewport.scrollLeft=photoDrag.left-(e.clientX-photoDrag.x);photoPanViewport.scrollTop=photoDrag.top-(e.clientY-photoDrag.y)});
for(const type of ['pointerup','pointercancel','lostpointercapture'])photoPanViewport.addEventListener(type,()=>{photoDrag=null;photoPanViewport.classList.remove('is-dragging')});
let lightboxStartX=null;
lightbox.addEventListener('touchstart',e=>{if(e.touches.length===1)lightboxStartX=e.touches[0].clientX},{passive:true});
lightbox.addEventListener('touchend',e=>{if(lightboxStartX===null)return;const dx=e.changedTouches[0].clientX-lightboxStartX;lightboxStartX=null;if(Math.abs(dx)>60&&galleryZoom===1)changeGallery(dx<0?1:-1)},{passive:true});
document.addEventListener('keydown',e=>{
 if(!lightbox.open&&!pathNow().startsWith('/product/'))return;
 if(e.target instanceof HTMLElement && (e.target.matches('input,textarea,select')||e.target.isContentEditable))return;
 if(e.key==='ArrowRight'){e.preventDefault();changeGallery(1)}
 else if(e.key==='ArrowLeft'){e.preventDefault();changeGallery(-1)}
 else if(lightbox.open&&(e.key==='+'||e.key==='=')){e.preventDefault();setGalleryZoom('in')}
 else if(lightbox.open&&e.key==='-'){e.preventDefault();setGalleryZoom('out')}
 else if(lightbox.open&&e.key==='0'){e.preventDefault();setGalleryZoom('reset')}
});
